.comment-write .wrt-footer .comment-text-cur {color:#000}
.comment-write .wrt-footer .btn-comment-save {float:right;height:32px;padding:0 1.125rem;font-size:.8125rem;line-height:1;color:#fff;border-radius:.25rem;background-color:#68A4DF;cursor:pointer}
@media screen and (max-width: 39.9375em) { .row .comment-write .user-name, .row #comment-guest {float:none;width:auto} .row .comment-write .user-name {display:block;margin-bottom:.375rem} .row .comment-write .btn-comment-login {text-decoration:underline} .row .comment-write .btn-comment-login::before {content:"\e9f5";display:inline-block;margin-right:.375rem;font:14px/1 fontello;font-size:inherit;text-rendering:auto;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale} .row #comment-guest input[type="text"], .row #comment-guest input[type="password"] {width:calc(50% - .125rem)} .row .comment-write .comment-content {min-height:80px;font-size:.875rem} .row .comment-write .recaptcha-container {overflow:hidden;max-width:100%}
