#AD162866094474.ad-template .col .ad-view { position:relative; } (adsbygoogle = window.adsbygoogle || []).push({}); 당초 출사표를 던졌던 권백신 전 예비후보가 돌연 사퇴 후 권광택 캠프에 합류하면서 ‘보수 단일’을 주장했지만 권기창·김의승 캠프 측에서는 낮은 지지율 회복을 위한 그들만의 ‘정치쇼’라고 일축했고, 실제 권백신 후보 합류 이후 각 종 여론조사에서 나타난 권광택 후보 지지율 추이도 저점에서 반등시키지 못하며 실패한 흥행성적을 남겼다. 한술 더 떠 현역 시도의원 지지선언 종용에 이어 이들을 대책회의를 이유로 시도 때도 없이 특정 캠프로 호출하는데다, 읍면동 당협위원장까지 동원해 지지선언과 지지 메시지 유포를 유도하고 있지만 당심으로까지 확산되지 않으면서 선거 여론을 환기시키는데는 역부족이라는 평가다. 이런 상황에서 당초 기대했던 세력 확장은 고사하고 오히려 당협위원장이 주례를 맡은 ‘쇼윈도 부부’라는 지역정가의 비판이 없을리 없다. '해당행위' 으름장에 불쏘시개로 전락한 광역·기초의원 후보도 갈 길을 잃은 것은 마찬가지. 여기에 본 후보 등록이 20여일 남짓되는 시점에서 보이지 않는 힘들이 경북도당 공관위 비선과 접촉했다며 컷오프, 단수공천, 2인 경선 등 아전인수격 해석을 내놓는데다, 무소속연대설까지 난무하며 안동시장 선거가 올해 전국 지방선거판의 ‘축소판’이 되고 있다는 악평이다. 예천군수의 경우 기약없는 안동시장 후보 공천 때문에 덩달아 밀리고 있다는 의견도 있지만 현장의 세평은 현역과 도전자간 싸움이 안동시와 흡사 다르지 않다는 시각이 우세하다. 반대로 더불어민주당은 일찌감치 이삼걸 전 행정안전부 차관을 후보로 낙점하고 현장을 누비며 세력 확장에 속도를 내고 있어 극명한 대조를 나타내고 있다. 특히 이재명 대통령의 고향이라는 명분과 각 종 국책사업이나 국가예산 확보에 여당의 힘이 절대적이라는 잇점을 앞세워 ‘보수의 심장’을 파고 들고 있다. 이른바 '분위기 좋은' 이삼걸 예비후보는 연일 전통시장과 경제단체, 유림단체 등을 돌며 밑바닥 민심의 훑고 있고 오중기 경북도지사 후보와 기초의원 후보로 확정된 후보까지 연대해 안동 대통령과 안동 민주당이 만드는 안동의 미래에 탄력을 붙이고 있다. 이에 더해 최근에는 안동에서 한일정상회담 5월 개최가 확정적이라는 보도가 잇따르는가 하면 안동 국립의대 신설 또한 발표만 앞두고 있다는 설까지 더해지면서 꿈쩍않을 것 같던 안동의 표심도 크게 요동치는 정황이 속속 목격되고 있다. 뿐만 아니라 바닥을 치는 국민의힘의 지지율에 공천갈등, 안동에 상존하는 야성 30%, 안동권·김 주도의 장기 집권에 대한 반발심까지 복합적으로 작용할 경우 결과를 장담할 수 없다는 해석이 파다하다. 여차하면 ‘파란 안동’으로 뒤집어질 공산도 농후한게 이번 지방선거다. 기세로운 여당의힘과 갈팡질팡하는 국민의힘. 한번도 경험해 보지 못한 '보수의험지' 신세 안동의 지방선거다. var ___BANNER = "ban_1776424271";var ___BANNER = "ban_1776424278";var ___BANNER = "ban_1776243317";var ___BANNER = "ban_1774248858";var ___BANNER = "ban_1774345029";var ___BANNER = "ban_1776243308";var ___BANNER = "ban_1773911373";var ___BANNER = "ban_1776424325";var ___BANNER = "ban_1770280440";var ___BANNER = "ban_1776057534";var ___BANNER = "ban_1776057541";var ___BANNER = "ban_1766554864";var ___BANNER = "ban_1765869848";var ___BANNER = "ban_1764846087";var ___BANNER = "ban_1767167255";var ___BANNER = "ban_1769401326";va