#AD166434356082.ad-template .col .ad-view { position:relative; } 앞서 이용균 시의원은 이날 이승훈 예비후보와 만나 지지의사를 전했고 양측캠프 관계자들도 같이 회동에 참석해 물리적 결합 추진을 협의한 것으로 전해졌다. 이와 관련 이승훈 예비후보는 청년투데이와의 통화에서 “이용균 시의원이 이승훈 예비후보를 지지한 것은 이승훈이 이재명 정부의 성공을 위해 지방정부를 이끌 적임자로 본 것”이라고 자신에 대한 지지이유를 설명했다. 이어서 “이용균 예비후보가 재개발 재건축을 3년 앞당기는 신속 추진 공약을 약속했고 또한 어린아이가 많아지는 등 인구가 늘어나 활력이 넘치는 강북구를 만들겠다고 공약했는데 이 같은 공약을 제가 이어 받아 추진하겠다”고 약속했다. 끝으로 그는 “오늘 이용균 예비후보 캠프관계자들과 회동을 통해 우리 캠프를 어떻게 발전시킬 것인지에 대해서도 이야기를 나누었다”면서 “느슨한 결합이 아닌 단단한 캠프로 발전시키는 내용들을 공유했다”고 힘주어 말했다. 장효남 기자 woorijang@daum.net 기자의 다른 기사 보기 열정, 노력, 꿈 그리고 청년투데이 저작권자 © 청년투데이 무단전재 및 재배포 금지 홈으로 위로 기사제보 기사 댓글 1 댓글 접기 로그인 후 이용 가능합니다. 댓글 내용입력 0 / 400 비회원 로그인 이름 비밀번호 댓글 내용입력 0 / 400 등록 댓글쓰기 계정을 선택하시면 로그인·계정인증을 통해 댓글을 남기실 수 있습니다. 회원 로그인 비회원 글쓰기 이름 비밀번호 자동등록방지 var captchaContainer = null; var reCapVal; var loadCaptcha = function() { grecaptcha.render('captcha_container', { 'sitekey' : '6LdFE_MZAAAAAO5daig6BaCqTKoVLUqny6LubX6p', 'callback' : function(response) { reCapVal = response; $("#nomember-captcha").val( reCapVal ); }, 'expired-callback': fnGcCallback }); }; var fnGcCallback = function() { grecaptcha.reset(); $('#btn-nomember-write').removeClass('on').trigger('click'); $("#reply-modal").foundation('open'); }; 확인 취소 로그인 옵션 창닫기 댓글목록 최신순 추천순 욕설, 타인비방 등의 게시물은 예고 없이 삭제 될 수 있습니다. 이승훈 이기자 2026-04-16 15:17:41 더보기 삭제하기 이승훈이 반드시 이겨야지 답글쓰기 4 0 이승훈 이기자 2026-04-16 15:17:41 더보기 삭제하기 이승훈이 반드시 이겨야지 답글쓰기 4 0

